insert into CHB_PRD_PERIODYIELD (SEQNO, PROD_ID, CHANGE_DATE, PROFIT_TYPE,CHANGE_TYPE, PROD_YIELD,PROD_BENCHMARK_RATE,UNIT_VALUE_TOTAL, UNIT_VALUE,SEVEN_DAY_RATE, ORG_CODE, DEPT_CODE, STATUS, REV_DATE, DATA_SOURCE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, REMARK,CCY) values (
select #{dto.seqno,jdbcType=CHAR}, #{dto.prodId,jdbcType=VARCHAR}, #{dto.fprodId,jdbcType=VARCHAR},#{dto.isLay,jdbcType=VARCHAR}, #{dto.changeDate,jdbcType=TIMESTAMP}, #{dto.profitType,jdbcType=VARCHAR},#{dto.changType,jdbcType=VARCHAR}, #{dto.prodYield,jdbcType=DECIMAL},#{dto.prodBenchmarkRate,jdbcType=DECIMAL},#{dto.unitValueTotal,jdbcType=DECIMAL}, #{dto.unitValue,jdbcType=DECIMAL},#{dto.sevenDayRate,jdbcType=DECIMAL}, #{dto.orgCode,jdbcType=VARCHAR}, #{dto.deptCode,jdbcType=VARCHAR}, #{dto.status,jdbcType=VARCHAR}, #{dto.revDate,jdbcType=TIMESTAMP}, #{dto.dataSource,jdbcType=VARCHAR}, #{dto.updateUser,jdbcType=VARCHAR}, now(), #{dto.createUser,jdbcType=VARCHAR}, now(), #{dto.remark,jdbcType=VARCHAR}, #{dto.ccy,jdbcType=VARCHAR} from dual
)

