mapper.insert:
insert into CHB_PRD_RATE(SEQNO, PROD_ID,FPROD_ID,IS_LAY, CHANGE_DATE, CASHMDATE,PROFIT_TYPE,CHANGE_TYPE, PROD_YIELD,PROD_BENCHMARK_RATE,UNIT_VALUE_TOTAL, UNIT_VALUE,SEVEN_DAY_RATE, ORG_CODE, DEPT_CODE, STATUS, REV_DATE, DATA_SOURCE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, REMARK,CCY) select SEQNO, PROD_ID,FPROD_ID,IS_LAY, CHANGE_DATE, CASHMDATE,PROFIT_TYPE,CHANGE_TYPE, PROD_YIELD,PROD_BENCHMARK_RATE,UNIT_VALUE_TOTAL, UNIT_VALUE,SEVEN_DAY_RATE, ORG_CODE, DEPT_CODE, STATUS, REV_DATE, DATA_SOURCE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, REMARK,CCY from ( select TEMP.* from (
SELECT #{item.seqno,jdbcType=CHAR} SEQNO, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.isLay,jdbcType=VARCHAR} IS_LAY, #{item.changeDate,jdbcType=TIMESTAMP} CHANGE_DATE, #{item.cashmdate,jdbcType=TIMESTAMP} CASHMDATE, #{item.profitType,jdbcType=VARCHAR} PROFIT_TYPE, #{item.changType,jdbcType=VARCHAR} CHANGE_TYPE, #{item.prodYield,jdbcType=DECIMAL} PROD_YIELD, #{item.prodBenchmarkRate,jdbcType=DECIMAL} PROD_BENCHMARK_RATE, #{item.unitValueTotal,jdbcType=DECIMAL} UNIT_VALUE_TOTAL, #{item.unitValue,jdbcType=DECIMAL} UNIT_VALUE, #{item.sevenDayRate,jdbcType=DECIMAL} SEVEN_DAY_RATE, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.revDate,jdbcType=TIMESTAMP} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, now() UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, now() CREATE_TIME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.ccy,jdbcType=VARCHAR} ccy FROM DUAL
) TEMP where not exists (select 1 from CHB_PRD_RATE CII where CII.PROD_ID = TEMP.PROD_ID AND DATE_FORMAT(CII.CHANGE_DATE,'%Y-%m-%d') = DATE_FORMAT(TEMP.CHANGE_DATE,'%Y-%m-%d') AND CII.PROFIT_TYPE = TEMP.PROFIT_TYPE AND CII.CHANGE_TYPE = TEMP.CHANGE_TYPE) ) de ;
UPDATE CHB_PRD_RATE as A, ( select PROD_YIELD, PROD_BENCHMARK_RATE, UNIT_VALUE_TOTAL, UNIT_VALUE, SEVEN_DAY_RATE, ORG_CODE, DEPT_CODE, REV_DATE, STATUS, REMARK, UPDATE_USER, UPDATE_TIME, CCY, CASHMDATE from ( select TEMP.* from (
SELECT #{item.seqno,jdbcType=CHAR} SEQNO, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.isLay,jdbcType=VARCHAR} IS_LAY, #{item.changeDate,jdbcType=TIMESTAMP} CHANGE_DATE, #{item.cashmdate,jdbcType=TIMESTAMP} CASHMDATE, #{item.profitType,jdbcType=VARCHAR} PROFIT_TYPE, #{item.changType,jdbcType=VARCHAR} CHANGE_TYPE, #{item.prodYield,jdbcType=DECIMAL} PROD_YIELD, #{item.prodBenchmarkRate,jdbcType=DECIMAL} PROD_BENCHMARK_RATE, #{item.unitValueTotal,jdbcType=DECIMAL} UNIT_VALUE_TOTAL, #{item.unitValue,jdbcType=DECIMAL} UNIT_VALUE, #{item.sevenDayRate,jdbcType=DECIMAL} SEVEN_DAY_RATE, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.revDate,jdbcType=TIMESTAMP} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, now() UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, now() CREATE_TIME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.ccy,jdbcType=VARCHAR} ccy FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_PRD_RATE CII where CII.PROD_ID = TEMP.PROD_ID AND DATE_FORMAT(CII.CHANGE_DATE,'%Y-%m-%d') = DATE_FORMAT(TEMP.CHANGE_DATE,'%Y-%m-%d') AND CII.PROFIT_TYPE = TEMP.PROFIT_TYPE AND CII.CHANGE_TYPE = TEMP.CHANGE_TYPE);
